insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'President & Chair, Governing Council', 'amara-okafor', '18+ years across power systems engineering, technical programme leadership and professional development.', 'Amara is an illustrative senior electrical engineer profile created for this website concept. Her profile represents the kind of national leadership that sets professional priorities, convenes stakeholders and translates institutional strategy into measurable programmes for members and the engineering sector.', '{"name": "Engr. Amara Okafor", "title": "President & Chair, Governing Council", "group": "National Executive Committee", "sampleProfile": true, "email": "amara.okafor@example.org", "location": "Abuja, Nigeria", "qualifications": ["B.Eng. Electrical Engineering", "M.Eng. Power Systems Engineering", "Registered Engineer (COREN)"], "experience": "18+ years across power systems engineering, technical programme leadership and professional development.", "career": [{"role": "Director, Engineering Programmes", "org": "National Infrastructure & Energy Group", "period": "2020–present"}, {"role": "Lead Power Systems Engineer", "org": "Grid Modernisation Partnership", "period": "2014–2020"}, {"role": "Electrical Engineer", "org": "Integrated Engineering Services", "period": "2008–2014"}], "expertise": ["Power system planning and reliability", "Professional standards and ethics", "Strategic governance and stakeholder engagement", "Mentorship and continuing professional development"], "responsibilities": ["Set strategic direction and annual priorities", "Chair council and executive meetings", "Represent the institute in professional and public forums", "Review delivery against the institute’s work programme"], "priorities": ["Member value and professional growth", "Ethical, safe and reliable engineering practice", "Stronger regional chapters and industry collaboration"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Deputy President & Vice-Chair, Council', 'tunde-balogun', '16 years in electronics, engineering operations, technical committees and professional capacity building.', 'Tunde is an illustrative deputy-president profile focused on leadership continuity, cross-portfolio coordination and delivery discipline. The role supports the president, helps align section plans and follows through on agreed council decisions.', '{"name": "Engr. Tunde Balogun", "title": "Deputy President & Vice-Chair, Council", "group": "National Executive Committee", "sampleProfile": true, "email": "tunde.balogun@example.org", "location": "Lagos, Nigeria", "qualifications": ["B.Eng. Electronic Engineering", "M.Sc. Engineering Management", "Registered Engineer (COREN)"], "experience": "16 years in electronics, engineering operations, technical committees and professional capacity building.", "career": [{"role": "Engineering Operations Manager", "org": "Digital Systems & Controls Ltd.", "period": "2019–present"}, {"role": "Senior Electronics Engineer", "org": "Applied Technology Partners", "period": "2013–2019"}, {"role": "Systems Engineer", "org": "Industrial Automation Works", "period": "2009–2013"}], "expertise": ["Electronics and systems integration", "Programme management", "Governance and risk oversight", "Industry partnerships"], "responsibilities": ["Support the president and preside when delegated", "Coordinate cross-section priorities", "Track implementation of council decisions", "Support leadership transition and continuity"], "priorities": ["Reliable execution of approved programmes", "Collaboration across technical sections", "Professional development for early-career engineers"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Executive Secretary & Head of Secretariat', 'ifeoma-eze', '14 years in technical administration, programme delivery, member services and organisational operations.', 'Ifeoma is an illustrative secretariat leadership profile. It demonstrates the operational depth expected of the office responsible for coordinating meetings, maintaining records, supporting member services and ensuring approved decisions move into delivery.', '{"name": "Engr. Ifeoma Eze", "title": "Executive Secretary & Head of Secretariat", "group": "National Secretariat", "sampleProfile": true, "email": "ifeoma.eze@example.org", "location": "Abuja, Nigeria", "qualifications": ["B.Sc. Electrical/Electronic Engineering", "MBA, Public Sector Management", "Certified Project Management Professional"], "experience": "14 years in technical administration, programme delivery, member services and organisational operations.", "career": [{"role": "Head, Corporate Services", "org": "Engineering Programmes Office", "period": "2021–present"}, {"role": "Programme Coordination Lead", "org": "Technical Capacity Initiative", "period": "2016–2021"}, {"role": "Project Officer", "org": "Professional Services Network", "period": "2011–2016"}], "expertise": ["Secretariat operations and governance records", "Member communications and service delivery", "Event and programme coordination", "Reporting, procurement and administration"], "responsibilities": ["Coordinate day-to-day secretariat operations", "Maintain official records and action registers", "Support meetings, events and member communication", "Prepare implementation and performance reports"], "priorities": ["Responsive member support", "Reliable records and transparent processes", "Consistent delivery across chapters and sections"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Section Lead, Power & Clean Energy', 'chidi-nwosu', '15 years in distribution networks, renewable-energy integration and power infrastructure projects.', 'Chidi is an illustrative technical-section leader profile showing how a specialist portfolio connects practitioners, industry and research around practical power and clean-energy challenges.', '{"name": "Engr. Chidi Nwosu", "title": "Section Lead, Power & Clean Energy", "group": "Technical Section Leadership", "sampleProfile": true, "email": "chidi.nwosu@example.org", "location": "Enugu, Nigeria", "qualifications": ["B.Eng. Electrical Engineering", "M.Eng. Energy Systems", "Registered Engineer (COREN)"], "experience": "15 years in distribution networks, renewable-energy integration and power infrastructure projects.", "career": [{"role": "Principal Power Systems Engineer", "org": "Sustainable Grid Engineering", "period": "2020–present"}, {"role": "Distribution Planning Engineer", "org": "Regional Power Solutions", "period": "2014–2020"}, {"role": "Electrical Design Engineer", "org": "Utility Infrastructure Partners", "period": "2009–2014"}], "expertise": ["Power distribution and protection", "Solar and hybrid energy systems", "Grid integration and reliability", "Energy efficiency and safety"], "responsibilities": ["Develop the section’s annual technical work plan", "Organise seminars, site visits and CPD sessions", "Build links with utilities, manufacturers and researchers", "Promote engineering standards and practice notes"], "priorities": ["Reliable power infrastructure", "Clean-energy skills and integration", "Technical learning based on field experience"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Section Lead, Avionics & Space Systems', 'zainab-yusuf', '12 years across communications electronics, embedded control and safety-critical systems.', 'Zainab is an illustrative specialist leader profile for the avionics and space portfolio. It presents a credible professional pathway across electronic systems, communications, control, safety and technical learning.', '{"name": "Engr. Zainab Yusuf", "title": "Section Lead, Avionics & Space Systems", "group": "Technical Section Leadership", "sampleProfile": true, "email": "zainab.yusuf@example.org", "location": "Kaduna, Nigeria", "qualifications": ["B.Eng. Electronic Engineering", "M.Sc. Communications Systems", "Avionics Systems Safety Certificate"], "experience": "12 years across communications electronics, embedded control and safety-critical systems.", "career": [{"role": "Avionics Systems Specialist", "org": "Aerospace Technology Centre", "period": "2020–present"}, {"role": "Communications Systems Engineer", "org": "Mission Systems Engineering", "period": "2015–2020"}, {"role": "Electronics Engineer", "org": "Advanced Instrumentation Lab", "period": "2012–2015"}], "expertise": ["Avionics electronics and systems assurance", "Satellite communications fundamentals", "Embedded control and instrumentation", "Safety and reliability engineering"], "responsibilities": ["Set section learning priorities and technical events", "Connect members with aerospace and research organisations", "Encourage applied research and knowledge sharing", "Promote safety-minded engineering practice"], "priorities": ["Aviation and space technology awareness", "Systems safety and reliability", "Early-career specialist development"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Section Lead, Embedded & Emerging Technologies', 'emeka-obi', '13 years in embedded electronics, industrial IoT, product prototyping and technology transfer.', 'Emeka is an illustrative section leader profile representing the bridge between embedded engineering, product development and emerging technology. His sample portfolio demonstrates how a technical division can support practitioners through labs, workshops and applied case studies.', '{"name": "Engr. Emeka Obi", "title": "Section Lead, Embedded & Emerging Technologies", "group": "Technical Section Leadership", "sampleProfile": true, "email": "emeka.obi@example.org", "location": "Port Harcourt, Nigeria", "qualifications": ["B.Eng. Computer Engineering", "M.Eng. Embedded Systems", "IoT Systems Design Certificate"], "experience": "13 years in embedded electronics, industrial IoT, product prototyping and technology transfer.", "career": [{"role": "Embedded Systems Lead", "org": "Connected Devices Engineering", "period": "2021–present"}, {"role": "Senior Firmware Engineer", "org": "Industrial IoT Works", "period": "2016–2021"}, {"role": "Hardware Design Engineer", "org": "Applied Computing Studio", "period": "2012–2016"}], "expertise": ["Microcontrollers and firmware", "Industrial IoT and sensor systems", "Hardware-software integration", "Prototyping and product validation"], "responsibilities": ["Curate technical workshops and demonstrations", "Build a community of practice around emerging tools", "Promote safe, maintainable system design", "Connect researchers, startups and industry practitioners"], "priorities": ["Hands-on technical learning", "Responsible adoption of emerging technology", "Product engineering and local innovation"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Section Lead, Information & Communications Technology', 'nkechi-adeyemi', '14 years in telecom infrastructure, network performance, fibre deployment and digital-service resilience.', 'Nkechi is an illustrative ICT section leader profile. It demonstrates a portfolio that brings together communications infrastructure, network engineering, resilience and professional development for practitioners working across the digital economy.', '{"name": "Engr. Nkechi Adeyemi", "title": "Section Lead, Information & Communications Technology", "group": "Technical Section Leadership", "sampleProfile": true, "email": "nkechi.adeyemi@example.org", "location": "Ibadan, Nigeria", "qualifications": ["B.Eng. Telecommunications Engineering", "M.Sc. Network Engineering", "Certified Network Professional"], "experience": "14 years in telecom infrastructure, network performance, fibre deployment and digital-service resilience.", "career": [{"role": "Network Engineering Manager", "org": "National Connectivity Services", "period": "2020–present"}, {"role": "Senior Radio Access Engineer", "org": "Telecom Infrastructure Group", "period": "2015–2020"}, {"role": "Telecommunications Engineer", "org": "Network Deployment Partners", "period": "2011–2015"}], "expertise": ["Telecommunications networks and fibre", "Radio access and network optimisation", "Infrastructure resilience and quality of service", "Digital inclusion and connectivity"], "responsibilities": ["Coordinate technical learning and section programmes", "Engage operators, regulators and equipment providers", "Promote good engineering practice and knowledge exchange", "Identify skills gaps and training opportunities"], "priorities": ["Resilient digital infrastructure", "Practical network engineering skills", "Collaboration between academia and industry"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Section Lead, Instrumentation, Control & Automation', 'samuel-okorie', '17 years in industrial instrumentation, process automation, control-system integration and commissioning.', 'Samuel is an illustrative technical leader profile for instrumentation, control and automation. The profile models the practical depth expected in this division, from measurement and control architecture to commissioning, safety and industrial reliability.', '{"name": "Engr. Samuel Okorie", "title": "Section Lead, Instrumentation, Control & Automation", "group": "Technical Section Leadership", "sampleProfile": true, "email": "samuel.okorie@example.org", "location": "Warri, Nigeria", "qualifications": ["B.Eng. Electrical Engineering", "M.Eng. Control Systems", "Industrial Functional Safety Training"], "experience": "17 years in industrial instrumentation, process automation, control-system integration and commissioning.", "career": [{"role": "Lead Automation Engineer", "org": "Process Control Engineering Ltd.", "period": "2019–present"}, {"role": "Control Systems Engineer", "org": "Industrial Integration Partners", "period": "2013–2019"}, {"role": "Instrumentation Engineer", "org": "Plant Reliability Services", "period": "2008–2013"}], "expertise": ["Instrumentation and process measurement", "PLC, SCADA and control systems", "Commissioning and troubleshooting", "Functional safety and industrial reliability"], "responsibilities": ["Plan specialist seminars and practical workshops", "Share field lessons and engineering case studies", "Promote safe system integration and maintenance", "Develop collaboration with industrial operators"], "priorities": ["Industrial safety and system reliability", "Automation capability development", "Knowledge sharing between practitioners"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('executive', 'Section Lead, Electronic & Computing Engineering', 'david-olumide', '11 years in digital electronics, computing hardware, instrumentation interfaces and applied engineering research.', 'David is an illustrative section leader profile for electronic and computing engineering. It demonstrates a portfolio linking circuit design, computing hardware, testing, applied research and technical capability building.', '{"name": "Engr. David Olumide", "title": "Section Lead, Electronic & Computing Engineering", "group": "Technical Section Leadership", "sampleProfile": true, "email": "david.olumide@example.org", "location": "Ilorin, Nigeria", "qualifications": ["B.Eng. Electronic Engineering", "M.Sc. Computer Engineering", "Applied Electronics Design Certificate"], "experience": "11 years in digital electronics, computing hardware, instrumentation interfaces and applied engineering research.", "career": [{"role": "Hardware Systems Engineer", "org": "Digital Engineering Laboratory", "period": "2020–present"}, {"role": "Electronics Design Engineer", "org": "Applied Computing Systems", "period": "2015–2020"}, {"role": "Graduate Engineer", "org": "Technology Research Workshop", "period": "2012–2015"}], "expertise": ["Digital electronics and circuit design", "Computing hardware and interfaces", "Testing, validation and troubleshooting", "Applied research and prototyping"], "responsibilities": ["Coordinate section activities and technical talks", "Encourage practical demonstrations and design reviews", "Connect members with labs, researchers and manufacturers", "Promote quality, safety and design documentation"], "priorities": ["Hands-on electronics capability", "Local product design and testing", "Industry-academia collaboration"]}'::jsonb, true, now())
insert into public.site_content (content_type,title,slug,summary,body,metadata,published,updated_at) values
  ('institutional_page','About NI4E','about','NI4E brings together professional interests across energy, electrical and electronics engineering.','NI4E provides a professional meeting point for people working across energy, electrical engineering and electronics. Its work connects technical knowledge with professional responsibility, collaboration and the practical needs of modern infrastructure.', '{"headline": "Engineering knowledge. Professional community. National progress.", "secondParagraph": "Our work spans professional development, knowledge exchange, responsible engineering practice and stronger connections between practitioners, educators, researchers, industry and emerging professionals.", "closingStatement": "Reliable energy systems, safe electrical installations and dependable electronics are central to economic activity and everyday life. NI4E supports the knowledge, judgement and collaboration needed to deliver these systems responsibly."}'::jsonb, true, now())
