-- NI4E Stage 2 content migration and starter records.
-- Leadership names, qualifications, work histories and example.org emails are fictional illustrative profiles.
-- This extends the allowed content types without changing existing RLS policies.
alter table public.site_content drop constraint if exists site_content_content_type_check;
alter table public.site_content add constraint site_content_content_type_check check (content_type in ('news','event','publication','chapter','executive','past_president','technical_division','document','project','committee','institutional_page'));

on conflict (content_type,slug) do update set title=excluded.title, summary=excluded.summary, body=excluded.body, metadata=excluded.metadata, published=true, updated_at=now();
